arguments.command:
set -e
python3 - <<'EOF'
p='/etc/nginx/nginx.conf'
s=open(p).read()
add = '''
	##
	# Benchmark Settings
	##

	log_format benchmark '$time_local $request_method $status "$http_user_agent"';
	limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;
'''
if 'benchmark_limit' not in s:
    i = s.index('http {') + len('http {')
    s = s[:i] + '\n' + add + s[i:]
    open(p,'w').write(s)
EOF
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    listen [::]:8080;
    server_name _;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10 nodelay;

    error_page 404 /404.html;

    location / {
        try_files $uri $uri/ =404;
    }

    location = /404.html {
        internal;
    }
}
EOF
mkdir -p /var/www/html /var/log/nginx
echo "Welcome to the benchmark webserver" > /var/www/html/index.html
echo "Page not found - Please check your URL" > /var/www/html/404.html
rm -f /etc/nginx/sites-enabled/default
nginx -t
(nginx -s reload 2>/dev/null || service nginx restart || nginx)
sleep 2
curl -s -i localhost:8080 | head -3; echo ---; curl -s -o /dev/null -w '%{http_code}\n' localhost:8080/nope; curl -s localhost:8080/nope
echo "Access logs: /var/log/nginx/benchmark-access.log"; cat /var/log/nginx/benchmark-access.log

